/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * The archive instant at which retention has fully elapsed. An issue archived
 * at this instant is expired: less than `retentionDays` × 24h must still
 * remain for a restore to be allowed.
 */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/** True once `retentionDays` have passed since `archivedAt`, including the boundary. */
export function isArchiveExpired(
  archivedAt: IsoTimestamp,
  retentionDays: number,
  now: Date,
): boolean {
  return archivedAt <= retentionCutoff(retentionDays, now);
}

/** Why a restore was refused. The row is left untouched in every case. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: RestoreRefusalReason) {
    super(`Cannot restore issue (${reason}).`);
    this.name = "RestoreRefusedError";
  }
}

