import {
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  projects,
} from "@/server/db";

/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

const BYTES_PER_MB = 1024 * 1024;

/**
 * Keeps the project's high-water issue number from moving backwards. Called
 * when a number is issued and again when that row is purged.
 */
function reserveIssueNumber(
  db: Pick<ReturnType<typeof getDb>, "update">,
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  db.update(projects)
    .set({
      lastIssueNumber: sql`max(${projects.lastIssueNumber}, ${issueNumber})`,
    })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .run();
}

