/**
 * Next per-project issue number. Archived issues keep their number, and a
 * purged issue keeps its number reserved on the project, so the max is taken
 * over the rows that remain and the project's high-water mark.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
