/**
 * The retention sweep. Soft-deleted issues are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Every expired issue in the workspace is deleted for good, together with its
 * label links, comments and attachments. Search documents for the issue and
 * its comments go with it, and the storage counter gives those attachments'
 * megabytes back. Issue numbers stay reserved. The audit-log purge is
 * unchanged: rows past the same window are removed outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(retentionDays, now);
      const issues = await listEveryIssue(orgId);

      for (const issue of issues) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        const purged = await issueRepo.purgeIssue(orgId, issue.id);
        if (!purged) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        for (const commentId of purged.commentIds) {
          await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
        }

        if (purged.storageMbReleased !== 0) {
          await usageRepo.incrementUsage(orgId, {
            storageMbUsed: -purged.storageMbReleased,
          });
        }

        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Every issue in the workspace, live or archived, walking past the page cap. */
async function listEveryIssue(orgId: OrgId): Promise<readonly Issue[]> {
  const issues: Issue[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await issueRepo.listIssues({
      orgId,
      limit: PAGE_SIZE,
      cursor,
      includeArchived: true,
    });
    issues.push(...page.items);
    if (page.nextCursor === null || page.nextCursor === cursor) return issues;
    cursor = page.nextCursor;
  }
}

