import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { getPlanLimits } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issues } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { listActivity } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { registerSearchListeners } from "@/server/services/search-service";
import { search } from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

describe("restore and purge", () => {
  let cleanup: () => void;
  const offs: Array<() => void> = [];

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    offs.push(registerActivityListeners());
    offs.push(registerSearchListeners());
    offs.push(registerUsageListeners());
  });

  afterAll(() => {
    for (const off of offs) off();
    cleanup();
  });

  it("restores within retention, records the audit row, and reindexes", async () => {
    const tenant = await createTenant("restore-ok", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Bring me back uniquely" }),
    );
    const number = issue.number;
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const before = await usageRepo.getUsage(tenant.org.id);
    const restored = await issueService.restoreIssue(
      tenant.actors.viewer.role === "viewer" && issue.authorId === tenant.actors.member.userId
        ? tenant.actors.member
        : tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(number);
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed + 1);

    const hits = await search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Bring me back uniquely",
      kinds: ["issue"],
      limit: 10,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toContain(issue.id);

    const activity = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.restored"],
      limit: 10,
      cursor: null,
    });
    expect(activity.items.some((row) => row.subjectId === issue.id)).toBe(true);
  });

  it("refuses not archived, expired, archived project, and quota without emitting", async () => {
    const tenant = await createTenant("restore-no", "free");
    await usageRepo.recomputeUsage(tenant.org.id);

    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still live issue" }),
    );
    const seen: string[] = [];
    const off = subscribe("issue.restored", () => {
      seen.push("x");
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id),
    ).rejects.toMatchObject({ reason: "not_archived" });

    const archived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Old archive issue" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);
    const days = getPlanLimits("free").retentionDays;
    const expiredAt = toIsoTimestamp(new Date(Date.now() - days * 24 * 60 * 60 * 1000));
    getDb().update(issues).set({ archivedAt: expiredAt }).where(eq(issues.id, archived.id)).run();
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, archived.id),
    ).rejects.toBeInstanceOf(RestoreRefusedError);

    const fresh = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Project archived issue" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, fresh.id);
    const { archiveProject } = await import("@/server/services/project-service");
    await archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, fresh.id),
    ).rejects.toMatchObject({ reason: "project_archived" });

    expect(seen).toEqual([]);
    off();
    expect(
      (await issueRepo.findIssueById(tenant.org.id, fresh.id))?.archivedAt,
    ).not.toBeNull();
  });

  it("lets the author restore regardless of role and rejects a stranger", async () => {
    const tenant = await createTenant("restore-perm", "growth");
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Viewer authored" }),
      tenant.userIds.viewer,
      number,
    );
    await issueRepo.archiveIssue(tenant.org.id, issue.id);
    const restored = await issueService.restoreIssue(
      tenant.actors.viewer,
      tenant.org.id,
      issue.id,
    );
    expect(restored.archivedAt).toBeNull();

    const other = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Not the viewers" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, other.id);
    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, other.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.restoreIssue(
        { ...tenant.actors.member, orgId: "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId },
        tenant.org.id,
        other.id,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        "01HZZZDDDDDDDDDDDDDDDDDDDD" as IssueId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("purges every expired issue, releases storage, and never reuses the number", async () => {
    const tenant = await createTenant("purge-me", "growth");
    await usageRepo.getUsage(tenant.org.id);

    const keep = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Keep live marker" }),
    );
    const recent = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Recent archive marker" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, recent.id);

    const doomed = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Doomed archive marker" }),
    );
    const comment = await commentRepo.insertComment(
      {
        orgId: tenant.org.id,
        issueId: doomed.id,
        body: "doomed comment body",
        parentId: null,
        mentionedUserIds: [],
      },
      tenant.userIds.member,
    );
    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "comment",
      comment.id,
      "doomed comment body",
      null,
    );
    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "issue",
      doomed.id,
      "Doomed archive marker",
      tenant.project.id,
    );
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "purge-label",
      color: "#112233",
      description: null,
    });
    await labelRepo.setIssueLabels(tenant.org.id, doomed.id, [label.id]);
    await attachmentRepo.insertAttachment(
      {
        orgId: tenant.org.id,
        issueId: doomed.id,
        filename: "a.bin",
        contentType: "application/octet-stream",
        sizeBytes: 1,
      },
      tenant.userIds.member,
    );
    await attachmentRepo.insertAttachment(
      {
        orgId: tenant.org.id,
        issueId: doomed.id,
        filename: "b.bin",
        contentType: "application/octet-stream",
        sizeBytes: 1024 * 1024 + 1,
      },
      tenant.userIds.member,
    );
    await usageRepo.incrementUsage(tenant.org.id, { storageMbUsed: 3 });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, doomed.id);
    const days = getPlanLimits("growth").retentionDays;
    const expiredAt = toIsoTimestamp(
      new Date(Date.now() - (days + 1) * 24 * 60 * 60 * 1000),
    );
    getDb().update(issues).set({ archivedAt: expiredAt }).where(eq(issues.id, doomed.id)).run();

    const extra: string[] = [];
    for (let i = 0; i < 105; i += 1) {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: `Bulk expired ${i}` }),
      );
      await issueRepo.archiveIssue(tenant.org.id, issue.id);
      extra.push(issue.id);
    }
    getDb()
      .update(issues)
      .set({ archivedAt: expiredAt })
      .where(eq(issues.orgId, tenant.org.id))
      .run();
    // The recent archive and the live issue were just overwritten. Put them back.
    getDb().update(issues).set({ archivedAt: null }).where(eq(issues.id, keep.id)).run();
    getDb()
      .update(issues)
      .set({ archivedAt: toIsoTimestamp(new Date()) })
      .where(eq(issues.id, recent.id))
      .run();

    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    const now = new Date();
    await runCleanupArchivedJob(now);

    expect(await issueRepo.findIssueById(tenant.org.id, doomed.id)).toBeNull();
    for (const id of extra) {
      expect(await issueRepo.findIssueById(tenant.org.id, id as IssueId)).toBeNull();
    }
    expect(await issueRepo.findIssueById(tenant.org.id, keep.id)).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, recent.id))?.archivedAt).not.toBeNull();
    expect(await commentRepo.findCommentById(tenant.org.id, comment.id)).toBeNull();
    expect(await attachmentRepo.listAttachments(tenant.org.id, doomed.id)).toEqual([]);
    expect(await labelRepo.listLabelsForIssues(tenant.org.id, [doomed.id])).toEqual({});
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(1);

    const issueHits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Doomed archive marker",
      kinds: ["issue"],
      limit: 10,
      cursor: null,
    });
    expect(issueHits.total).toBe(0);
    const commentHits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "doomed comment body",
      kinds: ["comment"],
      limit: 10,
      cursor: null,
    });
    expect(commentHits.total).toBe(0);

    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.storageMbUsed).toBe(usageBefore.storageMbUsed - (1 + 2));
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed);

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, doomed.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the purge" }),
    );
    expect(created.number).toBeGreaterThan(doomed.number);
    expect(created.number).toBeGreaterThan(105);
  });
});

