it("refuses a restore that would exceed the project issue quota, and allows the assignee", async () => {
  const tenant = await createTenant("restore-quota", "free");
  const held = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title: "Held for quota",
      assigneeId: tenant.userIds.viewer,
    }),
  );
  await issueService.archiveIssue(tenant.actors.member, tenant.org.id, held.id);

  for (let i = 0; i < 99; i += 1) {
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: `Fill ${i}` }),
    );
  }

  const restored = await issueService.restoreIssue(
    tenant.actors.viewer,
    tenant.org.id,
    held.id,
  );
  expect(restored.archivedAt).toBeNull();
  expect(restored.number).toBe(held.number);

  await issueService.archiveIssue(tenant.actors.member, tenant.org.id, held.id);
  await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "The hundredth" }),
  );
  await expect(
    issueService.restoreIssue(tenant.actors.member, tenant.org.id, held.id),
  ).rejects.toMatchObject({ reason: "quota" });
  expect(
    (await issueRepo.findIssueById(tenant.org.id, held.id))?.archivedAt,
  ).not.toBeNull();
});

